import * as THREE from 'three/webgpu';
import {
  mix,
  color,
  float,
  smoothstep,
  uv,
  vec3,
  Vector2Node,
  ColorNode,
  UVNode,
} from 'three/tsl';
import gsap from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{cinematicPrimitives:Array<{name:string,params:any}>}} cinematicPrimitives
 * @property {{textContent:Array<{type:string,content:string,lineHeight?:number}>}} textContent
 * @property {{background:string}} colors
 */

/**
 * @typedef {object} NodeContext
 * @property {{primitives:Record<string,Function>}} primitives
 * @property {{fontAtlas:Function}} fontAtlas
 * @property {{textureLoader:Function, glbLoader:Function}} loaders
 */

/**
 * Create the prism UI element.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ------- GROUP ------------------------------------------------------------
  const group = new THREE.Group();
  group.position.set(config.position?.x ?? 0, config.position?.y ?? 0, config.position?.z ?? 0);
  group.rotation.set(
    THREE.MathUtils.degToRad(config.rotation?.x ?? 0),
    THREE.MathUtils.degToRad(config.rotation?.y ?? 0),
    THREE.MathUtils.degToRad(config.rotation?.z ?? 0)
  );
  group.scale.set(config.scale?.x ?? 1, config.scale?.y ?? 1, config.scale?.z ?? 1);

  // ------- PRISM GEOMETRY ---------------------------------------------------
  const sideLength = 1.2;
  const prismLength = 1.8;
  const radius = sideLength / Math.sqrt(3); // cylinder approximation
  const prismGeometry = new THREE.CylinderGeometry(radius, radius, prismLength, 3, 1, true);
  prismGeometry.rotateZ(Math.PI / 2); // align axis horizontally (X)
  prismGeometry.rotateZ(THREE.MathUtils.degToRad(12));
  prismGeometry.rotateY(THREE.MathUtils.degToRad(20));

  // ------- PRISM MATERIAL (NodeMaterial) ------------------------------------
  const prismMaterial = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#101017'), // surface base
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    metalness: 0.0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    side: THREE.DoubleSide,
    transparent: true,
    envMapIntensity: 1.0,
  });

  const prismMesh = new THREE.Mesh(prismGeometry, prismMaterial);
  group.add(prismMesh);

  // ------- EMISSIVE CORE ----------------------------------------------------
  const coreGeometry = new THREE.OctahedronGeometry(0.35);
  const coreMaterial = new THREE.MeshBasicMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 2.2,
  });
  const coreMesh = new THREE.Mesh(coreGeometry, coreMaterial);
  prismMesh.add(coreMesh);

  // ------- BACK RIM LIGHT ---------------------------------------------------
  const rimLight = new THREE.DirectionalLight(new THREE.Color('#e8ecf2'), 1.5);
  rimLight.position.set(-2, 1, -1); // behind‑left
  rimLight.target.position.set(0, 0, 0);
  group.add(rimLight);
  group.add(rimLight.target);

  // ------- CAUSTIC STREAK ---------------------------------------------------
  const causticGeometry = new THREE.PlaneGeometry(2.4, 0.5);
  const uvNode = new UVNode();

  const stopA = new ColorNode('#ff2a38');
  const stopB = new ColorNode('#e8ecf2');
  const stopC = new ColorNode('#9fb0c4');

  const t = uvNode.x;

  const colAB = mix(stopA, stopB, smoothstep(float(0.2), float(0.5), t));
  const colABC = mix(colAB, stopC, smoothstep(float(0.5), float(0.8), t));

  const causticMaterial = new THREE.NodeMaterial();
  causticMaterial.transparent = true;
  causticMaterial.lights = false;
  causticMaterial.color = colABC;
  causticMaterial.opacity = float(0.35);
  causticMaterial.depthWrite = false;

  const causticMesh = new THREE.Mesh(causticGeometry, causticMaterial);
  causticMesh.rotation.x = -Math.PI / 2; // lay flat on floor
  causticMesh.position.y = -1.1;
  group.add(causticMesh);

  // ------- TEXT (HEADLINE & CAPTION) ----------------------------------------
  // Helper to create MSDF text meshes using the supplied fontAtlas utility.
  function createTextMesh(text, style, yOffset) {
    const { atlasTexture, glyphMetrics } = ctx.fontAtlas(0, text, style);
    // Simple plane sized to estimated glyph metrics (approximation)
    const plane = new THREE.PlaneGeometry(glyphMetrics.width, glyphMetrics.height);
    // MSDF material from '@/text' (assumed to expose createMsdfMaterial)
    const msdfMaterial = new THREE.NodeMaterial();
    msdfMaterial.transparent = true;
    msdfMaterial.lights = false;
    msdfMaterial.depthWrite = false;

    const uv = new UVNode();

    // Sample the SDF atlas
    const texNode = new THREE.TextureNode(atlasTexture);
    const sdf = texNode.sample(uv);

    // Typical MSDF approach: signed distance threshold and smoothstep
    const distance = sdf.r; // assuming red channel holds distance
    const threshold = float(0.5);
    const opacity = 1.0 - smoothstep(threshold - 0.02, threshold + 0.02, distance);
    const colorNode = new ColorNode(style.color ?? '#e8ecf2');

    msdfMaterial.color = colorNode;
    msdfMaterial.opacity = opacity;

    const mesh = new THREE.Mesh(plane, msdfMaterial);
    mesh.position.set(0, yOffset, 0);
    return mesh;
  }

  // Headline
  const headlineStyle = {
    fontSize: 68,
    fontWeight: 600,
    color: '#e8ecf2',
    letterSpacing: -0.005,
    lineHeight: 1.1,
    family: 'Lora',
  };
  const headlineMesh = createTextMesh('Light, machined.', headlineStyle, 1.75);
  group.add(headlineMesh);

  // Caption
  const captionStyle = {
    fontSize: 18,
    fontWeight: 400,
    color: '#e8ecf2',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    family: 'JetBrains Mono',
  };
  const captionMesh = createTextMesh('SAPPHIRE OVER DIAL / ZERO DISTORTION', captionStyle, 1.75 - 0.5);
  group.add(captionMesh);

  // ------- APPLY CINEMATIC PRIMITIVES ---------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(group, prim.params);
      }
    }
  }

  // ------- USERDATA HANDLERS & CLEANUP --------------------------------------
  group.userData.handlers = {};

  const timelines = [];

  group.userData.cleanup = () => {
    // Dispose geometries
    prismGeometry.dispose();
    coreGeometry.dispose();
    causticGeometry.dispose();
    // Dispose materials
    prismMaterial.dispose();
    coreMaterial.dispose();
    causticMaterial.dispose();

    // Dispose any MSDF textures created by fontAtlas
    // Assuming fontAtlas returns a texture we can dispose
    // (if not, this is a no‑op)
    // No GSAP timelines created directly here, but kill any stored.
    timelines.forEach((tl) => tl.kill());
  };

  return group;
}
